//! Residue P32: auditable reconciliation of unresolved and negative research residue.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;
pub const CONTENT_TYPE:&str="application/vnd.aurora.residue.reconciliation-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ResidueItem4{pub residue_id:String,pub class:String,pub evidence_state:String,pub owner:String,pub source_digest:String,pub negative_result:bool,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ReconciliationIntegrityRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub items:Vec<ResidueItem4>,pub required_item_order:Vec<String>,pub required_class_order:Vec<String>,pub replay_identity:String,pub policy_allowed:bool,pub protected_closure:bool,pub signed_manifest:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub item_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ReconciliationIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ReconciliationIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub item_order:Vec<String>,pub accepted_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub class_order:Vec<String>,pub owner_order:Vec<String>,pub source_order:Vec<String>,pub negative_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:ReconciliationIntegrityArtifact4}
#[derive(Debug,Error)] pub enum ReconciliationIntegrityError{#[error("reconciliation integrity input is invalid: {0}")] Invalid(String),#[error("reconciliation integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}
fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}
fn invalid(v:impl Into<String>)->ReconciliationIntegrityError{ReconciliationIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"residue","consumers":["replication registry","release reviewer","archival workbench","consortium administrator"],"behavior":format!("reconcile research residue at {scale} ({mode})"),"value":"prevents unresolved, negative, contradicted, or omitted research findings from disappearing at release boundaries","input_schema":"ReconciliationIntegrityRequest4@1","output_schema":"ReconciliationIntegrityCard7@1","effects":["emit:residue-card","retain:negative-finding","block:unsafe-reconciliation"],"permissions":["read:local-residue"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&ReconciliationIntegrityCard7)->Result<(),ReconciliationIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.request_id.is_empty()||c.purpose.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("reconciliation identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.item_order,&c.accepted_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.class_order,&c.owner_order,&c.source_order,&c.negative_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("reconciliation vectors are not canonical"));}}let ids=c.item_order.iter().collect::<BTreeSet<_>>();let states=c.accepted_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("residue states do not partition items"));}Ok(())}
pub fn qualify(q:&ReconciliationIntegrityRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<ReconciliationIntegrityCard7,ReconciliationIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.items.is_empty()||q.required_item_order.is_empty()||!canonical(&q.required_item_order)||!canonical(&q.required_class_order)||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.item_budget==0{return Err(invalid("reconciliation identity, ordering, digest, locality, boundary, or budget is invalid"));}let mut rows=q.items.clone();rows.sort_by(|a,b|a.residue_id.cmp(&b.residue_id));let mut seen=BTreeSet::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut classes=BTreeSet::new();let mut owners=BTreeSet::new();let mut sources=BTreeSet::new();let mut negative=BTreeSet::new();let mut evidence=BTreeSet::new();for i in &rows{if i.residue_id.trim().is_empty()||!seen.insert(i.residue_id.clone())||i.class.trim().is_empty()||i.evidence_state.trim().is_empty()||i.owner.trim().is_empty()||!digest(&i.source_digest)||!i.local||!i.aggregate_only{return Err(invalid("residue identity, class, owner, digest, evidence, or locality is invalid"));}classes.insert(format!("{}:{}",i.residue_id,i.class));owners.insert(format!("{}:{}",i.residue_id,i.owner));sources.insert(format!("{}:{}",i.residue_id,i.source_digest));evidence.insert(i.source_digest.clone());if i.negative_result{negative.insert(format!("{}:negative-result",i.residue_id));}if i.evidence_state=="unknown"||i.source_digest==q.replay_identity{unknown.insert(i.residue_id.clone());}else if i.class=="contradicted"||i.class=="unmeasured"{rejected.insert(i.residue_id.clone());}else if !q.required_item_order.contains(&i.residue_id){omitted.insert(i.residue_id.clone());}else{accepted.insert(i.residue_id.clone());}}let missing=q.required_item_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.signed_manifest||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||rows.len()>q.item_budget;if global{omitted.extend(seen.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||!unknown.is_empty(){"unknown"}else if !rejected.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let item_order=seen.iter().cloned().collect::<Vec<_>>();let accepted_order=accepted.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"item_order":item_order,"accepted_order":accepted_order,"rejected_order":rejected_order,"unknown_order":unknown_order,"omitted_order":omitted_order,"class_order":classes.into_iter().collect::<Vec<_>>(),"owner_order":owners.into_iter().collect::<Vec<_>>(),"source_order":sources.into_iter().collect::<Vec<_>>(),"negative_order":negative.into_iter().collect::<Vec<_>>(),"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let closure_digest=ContentHash::of_value(&body).map_err(|e|ReconciliationIntegrityError::Digest(e.to_string()))?.to_string();let effect_receipts=if disposition=="qualified"{vec![format!("approve:residue:{}",q.request_id)]}else{vec!["block:unsafe-reconciliation".into()]};let artifact=ReconciliationIntegrityArtifact4{artifact_id:format!("residue-reconciliation:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:body["omitted_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=ReconciliationIntegrityCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),item_order:body["item_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),accepted_order,rejected_order,unknown_order,omitted_order,class_order:body["class_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),owner_order:body["owner_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),source_order:body["source_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),negative_order:body["negative_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts,artifact};let _=(scale,mode);validate_card(&c)?;Ok(c)}
